private data class Bounds(val left:Float,val bottom:Float,val right:Float,val top:Float) {
    fun intersects(l:Float,b:Float,r:Float,t:Float)=right>=l&&left<=r&&top>=b&&bottom<=t
}
private data class CachedGeometry(val primitive:Primitive,val bounds:Bounds,val path:Path?=null,val oval:RectF?=null,val pattern:Path?=null)
private data class TextLayoutModel(val source:Primitive.Text,val lines:Array<String>,val unitWidths:FloatArray,val baselines:FloatArray,val bounds:Bounds,val font:ResolvedFont,val effectiveWidthFactor:Float)
private data class RenderModel(val geometry:List<CachedGeometry>,val texts:List<TextLayoutModel>,val bounds:Bounds,val buildMs:Double)

