    fun cancelMeasurement(){measuring=false;areaMode=false;measureStart=null;measureEnd=null;areaPoints.clear();invalidate()}
    fun fitToDrawing(){fitPending=true;invalidate()}
    fun setPalette(background:Int,foreground:Int,accent:Int){if(backgroundColor==background&&paint.color==foreground&&measurePaint.color==accent)return;backgroundColor=background;paint.color=foreground;textPaint.color=foreground;measurePaint.color=accent;hatchPaint.color=foreground;hatchPaint.alpha=55;invalidate()}

