    private fun nearestAreaVertex(x:Float,y:Float):Int{val limit=24f*resources.displayMetrics.density;var best=-1;var distance=limit*limit;for(i in areaPoints.indices){val p=areaPoints[i];val dx=tx+p.x.toFloat()*scale-x;val dy=ty-p.y.toFloat()*scale-y;val d=dx*dx+dy*dy;if(d<distance){distance=d;best=i}};return best}
    private fun screenPoint(x:Float,y:Float,snap:Boolean):Point2{val raw=Point2(((x-tx)/scale).toDouble(),((ty-y)/scale).toDouble());return if(snap)snapEndpoint(raw,(24f*resources.displayMetrics.density/scale).toDouble())?:raw else raw}

    private fun selectMeasurePoint(screenX:Float,screenY:Float){val raw=Point2(((screenX-tx)/scale).toDouble(),((ty-screenY)/scale).toDouble());val snapped=snapEndpoint(raw,(24f*resources.displayMetrics.density/scale).toDouble());val point=snapped?:raw;anySnapped=anySnapped||snapped!=null;if(areaMode){areaPoints+=point;notifyArea()}else if(measureStart==null){measureStart=point;onFirstMeasurePoint?.invoke()}else{measureEnd=point;val a=measureStart!!;onMeasurement?.invoke(hypot(point.x-a.x,point.y-a.y),model?.units?:DrawingUnit.UNKNOWN,anySnapped);measuring=false};invalidate()}
    private fun notifyArea(){var twice=0.0;if(areaPoints.size>=3)for(i in areaPoints.indices){val a=areaPoints[i];val b=areaPoints[(i+1)%areaPoints.size];twice+=a.x*b.y-b.x*a.y};onAreaChanged?.invoke(abs(twice)/2,model?.units?:DrawingUnit.UNKNOWN,areaPoints.size)}
    private fun snapEndpoint(target:Point2,tolerance:Double):Point2?{val m=model?:return null;var best:Point2?=null;var bestD=tolerance*tolerance;fun candidate(x:Double,y:Double){val d=(x-target.x).pow(2)+(y-target.y).pow(2);if(d<=bestD){bestD=d;best=Point2(x,y)}};for(p in m.primitives){if(!isLayerVisible(p.layerId))continue;when(p){is Primitive.Line->{candidate(p.x1,p.y1);candidate(p.x2,p.y2)};is Primitive.Polyline->for(i in p.points.indices step 2)candidate(p.points[i],p.points[i+1]);is Primitive.Arc->{candidate(p.cx+p.radius*cos(p.start),p.cy+p.radius*sin(p.start));candidate(p.cx+p.radius*cos(p.end),p.cy+p.radius*sin(p.end))};is Primitive.Ellipse->{fun ep(a:Double){val major=hypot(p.ax,p.ay);val angle=atan2(p.ay,p.ax);val lx=major*cos(a);val ly=major*p.ratio*sin(a);candidate(p.cx+lx*cos(angle)-ly*sin(angle),p.cy+lx*sin(angle)+ly*cos(angle))};ep(p.start);ep(p.end)};else->Unit}};return best}

    override fun onDraw(c:Canvas){val wallStart=System.nanoTime();val cpuStart=Debug.threadCpuTimeNanos();super.onDraw(c);c.drawColor(backgroundColor);val rm=renderModel?:return;if(fitPending){fit(rm.bounds);fitPending=false};val inv=1f/scale.coerceAtLeast(1e-5f);val vl=(0f-tx)*inv;val vr=(width-tx)*inv;val vb=(ty-height)*inv;val vt=ty*inv;var geometryNs=0L;var textNs=0L;var visibleGeometry=0;var lodRejected=0;var visibleTexts=0;c.save();c.translate(tx,ty);c.scale(scale,-scale);paint.strokeWidth=1.2f*inv;val gs=System.nanoTime();for(item in rm.geometry)if(isLayerVisible(item.primitive.layerId)&&item.bounds.intersects(vl,vb,vr,vt)){val tiny=(item.bounds.right-item.bounds.left)*scale<.65f&&(item.bounds.top-item.bounds.bottom)*scale<.65f;if(tiny&&item.primitive !is Primitive.Hatch){lodRejected++;continue};drawCached(c,item);visibleGeometry++};geometryNs=System.nanoTime()-gs;c.restore();val ts=System.nanoTime();visibleTexts=drawTexts(c,rm,vl,vb,vr,vt);textNs=System.nanoTime()-ts;drawMeasurement(c);profileFrame(wallStart,cpuStart,geometryNs,textNs,visibleGeometry,visibleTexts,lodRejected,rm);if(firstRenderPending){firstRenderPending=false;val firstMs=(System.nanoTime()-wallStart)/1e6;Log.i(TAG,"firstRenderMs=$firstMs primitives=${model?.primitives?.size} renderModelMs=${rm.buildMs}");onFirstRender?.invoke(firstMs)}}

    private fun drawTexts(c:Canvas,rm:RenderModel,vl:Float,vb:Float,vr:Float,vt:Float):Int{var visible=0;for(item in rm.texts){val p=item.source;if((!textVisible&&p.hideable)||!isLayerVisible(p.layerId)||p.height<=0.0||!item.bounds.intersects(vl,vb,vr,vt))continue;val capPixels=(p.height*scale).toFloat();if(capPixels<1.25f)continue;val size=capPixels/capHeightRatio;textPaint.typeface=item.font.typeface;textPaint.textSize=size;textPaint.textScaleX=item.effectiveWidthFactor;val horizontal=if(p.multiline)(p.horizontal-1).mod(3)else p.horizontal;c.save();c.translate(tx+p.x.toFloat()*scale,ty-p.y.toFloat()*scale);c.rotate(-Math.toDegrees(p.rotation).toFloat());for(index in item.lines.indices){val width=item.unitWidths[index]*size*item.effectiveWidthFactor;val x=when(horizontal){1->-width/2;2->-width;else->0f};c.drawText(item.lines[index],x,item.baselines[index]*size,textPaint)};c.restore();visible++};textPaint.textScaleX=1f;return visible}
