    private fun areaLabel(points:List<Point2>):String{var twice=0.0;for(i in points.indices){val a=points[i];val b=points[(i+1)%points.size];twice+=a.x*b.y-b.x*a.y};val area=abs(twice)/2;val factor=when(model?.units){DrawingUnit.MILLIMETERS->1.0;DrawingUnit.CENTIMETERS->10.0;DrawingUnit.METERS->1000.0;else->null};return if(factor==null)"%.2f кв. ед.".format(area) else "%.2f м²".format(area*factor*factor/1_000_000)}

    private fun buildRenderModel(m:DrawingModel):RenderModel{val started=System.nanoTime();val geometry=ArrayList<CachedGeometry>(m.primitives.size);val texts=ArrayList<TextLayoutModel>();var reportedTexts=0;var all:Bounds?=null;fun merge(b:Bounds){val a=all;all=if(a==null)b else Bounds(min(a.left,b.left),min(a.bottom,b.bottom),max(a.right,b.right),max(a.top,b.top))};val capRatio=capHeightRatio;textPaint.textSize=1f;for(p in m.primitives){when(p){is Primitive.Text->{val font=FontResolver.resolve(p);textPaint.typeface=font.typeface;val effective=(p.widthFactor*p.styleWidthFactor).toFloat().coerceIn(.1f,10f);val decoded=if(p.multiline)MTextDecoder.decode(p.value)else DecodedMText(p.value.replace("%%d","°",true),emptySet());val lines=layoutText(decoded.plainText,p,capRatio,effective);val widths=FloatArray(lines.size){textPaint.measureText(lines[it])};textPaint.textSize=100f;val fm=textPaint.fontMetrics;val advance=(5f/3f)*p.lineSpacing.toFloat()*capRatio;val block=(lines.size-1).coerceAtLeast(0)*advance+(fm.descent-fm.ascent)/100f;val vertical=if(p.multiline)(p.horizontal-1)/3 else p.vertical;val first=if(p.multiline)when(vertical){0->-fm.ascent/100f;1->-fm.ascent/100f-block/2;else->-fm.ascent/100f-block}else when(p.vertical){1->-fm.descent/100f;2->-(fm.ascent+fm.descent)/200f;3->-fm.ascent/100f;else->0f};val baselines=FloatArray(lines.size){first+it*advance};textPaint.textSize=1f;val width=max(p.boxWidth,if(widths.isEmpty())0.0 else widths.max().toDouble()*p.height*effective/capRatio);val blockHeight=p.height*((lines.size-1).coerceAtLeast(0)*(5.0/3.0)*p.lineSpacing+1.0);val radius=hypot(width,blockHeight).coerceAtLeast(p.height);val b=Bounds((p.x-radius).toFloat(),(p.y-radius).toFloat(),(p.x+radius).toFloat(),(p.y+radius).toFloat());texts+=TextLayoutModel(p,lines,widths,baselines,b,font,effective);merge(b);if(p.multiline&&reportedTexts++<12)Log.i(TAG,"textDebug raw=${p.value.take(240)} decoded=${decoded.plainText.take(240)} lines=${lines.contentToString()} style=${p.s